209	        }
210	        // Reject the request if the E.164 telephone is already used by another owner.
211	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
212	            throw new DuplicateTelephoneException(normalizedTelephone);
213	        }
214	        // Reject the request if the (normalized, lower-cased) email is already used by another owner.
215	        if (owner.getEmail() != null && isEmailInUse(owner.getEmail())) {
216	            throw new DuplicateEmailException(owner.getEmail());
217	        }
218	        // Reject the request if another owner already shares the same last name and address
219	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
220	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
221	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
222	        // every existing member that does not yet carry it.
223	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
224	        if (!householdMembers.isEmpty()) {
225	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
226	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
227	            }
228	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
229	            owner.setHouseholdId(householdId);
230	            for (Owner member : householdMembers) {
231	                if (!householdId.equals(member.getHouseholdId())) {
232	                    member.setHouseholdId(householdId);
233	                    this.clinicService.saveOwner(member);
234	                }
235	            }
236	        }
