241	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
242	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
243	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
244	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
245	        this.clinicService.saveOwner(owner);
246	        populateHouseholdSize(owner);
