293	
294	    /**
295	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
296	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
297	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
298	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
299	     *
300	     * @param city     the owner's city
301	     * @param lastName the owner's last name
302	     * @return the generated customer code
303	     */
304	    private String generateCustomerCode(String city, String lastName) {
305	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
306	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
307	        String normalizedCity = normalizeForComparison(city);
308	        int sequence = (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
310	            .count() + 1;
311	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
312	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
313	    }
314	
315	    /**
316	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
317	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
318	     * that is stored, returned and used for every value derived from it.
319	     *
320	     * @param date the effective registration date (supplied or defaulted)
321	     * @return the same date when it is a weekday, otherwise the next Monday
322	     */
323	    private LocalDate rollToBusinessDay(LocalDate date) {
324	        DayOfWeek dayOfWeek = date.getDayOfWeek();
325	        if (dayOfWeek == DayOfWeek.SATURDAY) {
326	            return date.plusDays(2);
327	        }
328	        if (dayOfWeek == DayOfWeek.SUNDAY) {
329	            return date.plusDays(1);
330	        }
331	        return date;
332	    }
333	
334	    /**
335	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
336	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
337	     *
338	     * @param customerCode     the owner's already-assigned customer code
339	     * @param registrationDate the owner's registration date
340	     * @return the generated membership number
341	     */
342	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
343	        String yy = String.format("%02d", registrationDate.getYear() % 100);
344	        return String.format("%s-M%s", customerCode, yy);
345	    }
346	
347	    /**
348	     * Count the existing owners that share the given first name and last name, comparing each
349	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
350	     * yet persisted, so it is not included in the count.
351	     *
352	     * @param firstName the incoming owner's first name
353	     * @param lastName  the incoming owner's last name
354	     * @return the number of existing namesakes
355	     */
356	    private int countNamesakes(String firstName, String lastName) {
357	        String normalizedFirstName = normalizeForComparison(firstName);
358	        String normalizedLastName = normalizeForComparison(lastName);
359	        return (int) this.clinicService.findAllOwners().stream()
360	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
361	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
362	            .count();
363	    }
364	
365	    /**
366	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
367	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
368	     *
369	     * @param city the incoming owner's city
370	     * @return the number of existing owners already in that city
371	     */
372	    private int countOwnersInCity(String city) {
373	        String normalizedCity = normalizeForComparison(city);
374	        return (int) this.clinicService.findAllOwners().stream()
375	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
376	            .count();
377	    }
378	
379	    /**
380	     * Count the existing owners whose registration date equals the given date. The incoming owner is
381	     * not yet persisted, so it is not included in the count.
382	     *
383	     * @param registrationDate the incoming owner's registration date
384	     * @return the number of existing owners already registered on that date
385	     */
386	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
387	        return (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
389	            .count();
390	    }
391	
392	    /**
393	     * Determine whether the given (already lower-cased) email is already used by any existing owner,
394	     * comparing case-insensitively. The incoming owner is not yet persisted, so it is not included.
395	     *
396	     * @param email the incoming owner's normalized email
397	     * @return {@code true} when another owner already uses that email
398	     */
399	    private boolean isEmailInUse(String email) {
400	        String normalizedEmail = email.toLowerCase(Locale.ROOT);
401	        return this.clinicService.findAllOwners().stream()
402	            .anyMatch(existing -> existing.getEmail() != null
403	                && existing.getEmail().toLowerCase(Locale.ROOT).equals(normalizedEmail));
404	    }
405	
406	    /**
407	     * Find the existing owners that live in the same household as the given values, i.e. those that
408	     * share both the last name and the address when each is compared case-insensitively with
409	     * collapsed whitespace.
410	     *
411	     * @param lastName the incoming owner's last name
412	     * @param address  the incoming owner's address
413	     * @return the matching existing owners (possibly empty)
414	     */
415	    private List<Owner> findHouseholdMembers(String lastName, String address) {
416	        String normalizedLastName = normalizeForComparison(lastName);
417	        String normalizedAddress = normalizeForComparison(address);
418	        return this.clinicService.findAllOwners().stream()
419	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
420	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
421	            .toList();
422	    }
423	
424	    /**
425	     * Generate a stable shared household identifier for the given last name and address. The value is
426	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
427	     * and address, so every owner joining the same household resolves to the same identifier. It is the
428	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
429	     *
430	     * @param lastName the household's last name
431	     * @param address  the household's address
432	     * @return the stable household identifier
433	     */
434	    private String generateHouseholdId(String lastName, String address) {
435	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
436	        try {
437	            byte[] digest = MessageDigest.getInstance("SHA-256")
438	                .digest(key.getBytes(StandardCharsets.UTF_8));
439	            StringBuilder sb = new StringBuilder(digest.length * 2);
440	            for (byte b : digest) {
441	                sb.append(String.format("%02x", b));
442	            }
443	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
444	        } catch (java.security.NoSuchAlgorithmException e) {
445	            throw new IllegalStateException("SHA-256 not available", e);
446	        }
447	    }
448	
449	    /**
450	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
451	     * single space, upper-case the result and expand common street-type abbreviations token by token
452	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
453	     * to the empty string. The result is the canonical form that is stored, returned and used for every
454	     * address comparison (household duplicate detection and the shared household id).
455	     *
456	     * @param address the raw address, may be {@code null}
457	     * @return the normalized address
458	     */
459	    private String normalizeAddress(String address) {
460	        if (address == null) {
461	            return "";
462	        }
463	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
464	        if (collapsed.isEmpty()) {
465	            return "";
466	        }
467	        String[] tokens = collapsed.split(" ");
468	        StringBuilder sb = new StringBuilder(collapsed.length());
469	        for (int i = 0; i < tokens.length; i++) {
470	            if (i > 0) {
471	                sb.append(' ');
472	            }
473	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
474	        }
475	        return sb.toString();
476	    }
477	
478	    /**
479	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
480	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
481	     *
482	     * @param value the raw value, may be {@code null}
483	     * @return the normalized value
484	     */
485	    private String normalizeForComparison(String value) {
486	        if (value == null) {
487	            return "";
488	        }
489	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
490	    }
491	
492	    /**
493	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
494	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
495	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
496	     * is returned lower-cased.
497	     *
498	     * @param email the raw email from the request payload, may be {@code null}
499	     * @return the lower-cased email, or {@code null} when none was provided
500	     */
501	    private String normalizeEmail(String email) {
502	        if (!StringUtils.hasText(email)) {
503	            return null;
504	        }
505	        if (!EMAIL_PATTERN.matcher(email).matches()) {
506	            throw new InvalidRequestException(List.of("email"));
507	        }
508	        return email.toLowerCase(Locale.ROOT);
509	    }
510	
511	    /**
512	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
513	     * already carries a leading '+' keeps its country code; otherwise the default country code
514	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
515	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
516	     * is thrown (mapped to 400 Bad Request).
517	     *
518	     * @param telephone the raw telephone from the request payload
519	     * @return the E.164 string (e.g. {@code +61412345678})
520	     */
521	    private String normalizeTelephone(String telephone) {
522	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
523	        String candidate;
524	        if (cleaned.startsWith("+")) {
525	            candidate = cleaned;
526	        } else {
527	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
528	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
529	        }
530	        if (!E164_PATTERN.matcher(candidate).matches()) {
531	            throw new InvalidRequestException(List.of("telephone"));
532	        }
533	        return candidate;
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Transactional
538	    @Override
539	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
540	        Owner owner = this.clinicService.findOwnerById(ownerId);
541	        if (owner == null) {
542	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	        }
544	        this.clinicService.deleteOwner(owner);
545	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
546	    }
547	
548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
551	        Owner owner = this.clinicService.findOwnerById(ownerId);
552	        if (owner == null) {
553	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	        }
555	        HttpHeaders headers = new HttpHeaders();
556	        Pet pet = petMapper.toPet(petFieldsDto);
557	        owner.setId(ownerId);
558	        pet.setOwner(owner);
559	        pet.getType().setName(null);
560	        this.clinicService.savePet(pet);
561	        PetDto petDto = petMapper.toPetDto(pet);
562	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
563	            .buildAndExpand(pet.getId()).toUri());
564	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
570	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
571	        if (currentOwner != null) {
572	            Pet currentPet = this.clinicService.findPetById(petId);
573	            if (currentPet != null) {
574	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
575	                currentPet.setName(petFieldsDto.getName());
576	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
577	                this.clinicService.savePet(currentPet);
578	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
579	            }
580	        }
581	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
582	    }
583	
584	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
585	    @Override
586	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
587	        HttpHeaders headers = new HttpHeaders();
588	        Visit visit = visitMapper.toVisit(visitFieldsDto);
589	        Pet pet = new Pet();
590	        pet.setId(petId);
591	        visit.setPet(pet);
592	        this.clinicService.saveVisit(visit);
593	        VisitDto visitDto = visitMapper.toVisitDto(visit);
594	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
595	            .buildAndExpand(visit.getId()).toUri());
596	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
597	    }
598	
599	
600	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
601	    @Override
602	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
603	        Owner owner = this.clinicService.findOwnerById(ownerId);
604	        if (owner != null) {
605	            Pet pet = owner.getPet(petId);
606	            if (pet != null) {
607	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
608	            }
609	        }
610	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
611	    }
612	}
